CREATE TABLE recalc_admin.whatsapp_flow_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id text NOT NULL UNIQUE,message_id text NOT NULL UNIQUE,event_type text NOT NULL,wa_id text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL,processed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recalc_admin.whatsapp_flow_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES recalc_admin.whatsapp_flow_events(id),message_id text NOT NULL UNIQUE,owner_user_id uuid NOT NULL,wa_id text NOT NULL,action text NOT NULL,data jsonb NOT NULL,problem_description text,queue_name text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recalc_admin.scheduled_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid NOT NULL REFERENCES recalc_admin.whatsapp_flow_submissions(id),action_type text NOT NULL,scheduled_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'pending',payload jsonb NOT NULL DEFAULT '{}',attempts int NOT NULL DEFAULT 0,locked_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,last_error text,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX scheduled_actions_due_idx ON recalc_admin.scheduled_actions(status,scheduled_at) WHERE cancelled_at IS NULL;
CREATE TABLE recalc_admin.contact_preferences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),wa_id text NOT NULL UNIQUE,unsubscribed boolean NOT NULL DEFAULT false,unsubscribed_at timestamptz,consent_audit jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recalc_admin.advisor_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid NOT NULL REFERENCES recalc_admin.whatsapp_flow_submissions(id),queue_name text NOT NULL,task_type text NOT NULL,status text NOT NULL DEFAULT 'open',due_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE recalc_admin.whatsapp_flow_events ENABLE ROW LEVEL SECURITY;ALTER TABLE recalc_admin.whatsapp_flow_submissions ENABLE ROW LEVEL SECURITY;ALTER TABLE recalc_admin.scheduled_actions ENABLE ROW LEVEL SECURITY;ALTER TABLE recalc_admin.contact_preferences ENABLE ROW LEVEL SECURITY;ALTER TABLE recalc_admin.advisor_tasks ENABLE ROW LEVEL SECURITY;
GRANT ALL ON recalc_admin.whatsapp_flow_events,recalc_admin.whatsapp_flow_submissions,recalc_admin.scheduled_actions,recalc_admin.contact_preferences,recalc_admin.advisor_tasks TO service_role;
